def max_sub_array_sum_repeated(arr, n, k):
    # Function to calculate maximum subarray sum using Kadane's algorithm
    def kadane(arr):
        size = len(arr)
        max_so_far = arr[0]
        current_max = arr[0]

        for i in range(1, size):
            current_max = max(arr[i], current_max + arr[i])
            max_so_far = max(max_so_far, current_max)

        return max_so_far

    # Function to compute maximum subarray sum when the array wraps around
    def modified_kadane(arr, n):
        overall = arr[0]
        temp = 0; max1 = arr[0]; max2 = arr[0]

        # First call of Kadane's algorithm
        for i in range(n):
            temp = temp + arr[i]
            if temp < arr[i]:
                temp = arr[i]
            if max1 < temp:
                max1 = temp

        temp = arr[0]
        if k == 1:
            return max1

        # Second call of Kadane's algorithm
        for i in range(n-1):
            temp = temp + arr[n-1-i-i]
            if temp > max2:
                max2 = temp

        s = 0
        for i in range(n):
            s += arr[i]

        overall = max(max1, max2 + (k-1)*s)

        return overall

    # Sum of the array
    arraySum = 0
    for i in range(n):
        arraySum += arr[i]

    # Case 1: If the number of repetitions is 1, then we can simply use Kadane's algorithm.
    # Case 2: If the arraySum is less than 0 and k is greater than 2, then the maximum subarray sum is obtained by the entire array repeated k times.
    # Case 3: If the arraySum is greater than 0 and k is greater than 2, we use modified Kadane's algorithm.
    if k == 1:
